INSERT INTO "DestinationTip" ("id","destinationId","topic","title","body","sourceUrl","position") SELECT 'tip_06cbec0d0f74320314e2', d."id", 'Safety', 'Cross the street at a steady pace', 'Walk at a slow, steady pace and don''t run or stop suddenly: motorbikes flow around you. Look both ways, even on one-way streets.', 'https://www.islands.com/1865824/what-to-know-before-vietnam-vacation/', 5 FROM "Destination" d WHERE d."slug" = 'hanoi' AND NOT EXISTS (SELECT 1 FROM "DestinationTip" t WHERE t."destinationId" = d."id" AND t."title" = 'Cross the street at a steady pace');
INSERT INTO "DestinationTip" ("id","destinationId","topic","title","body","sourceUrl","position") SELECT 'tip_b5ce32348bd8123978f3', d."id", 'Transport', 'Use Grab instead of street taxis', 'Grab shows the price up front, so there''s no bargaining or fast meter. Check the licence plate matches the app, and don''t let a driver cancel the trip partway.', 'https://www.islands.com/1865824/what-to-know-before-vietnam-vacation/', 6 FROM "Destination" d WHERE d."slug" = 'hanoi' AND NOT EXISTS (SELECT 1 FROM "DestinationTip" t WHERE t."destinationId" = d."id" AND t."title" = 'Use Grab instead of street taxis');
INSERT INTO "DestinationTip" ("id","destinationId","topic","title","body","sourceUrl","position") SELECT 'tip_c29eb923d17a2541f45b', d."id", 'Money', 'Check your 500,000 and 20,000 notes', 'The 500,000 dong note (about US$19) and the 20,000 note (about US$0.75) are almost the same colour. Count your change, and keep big and small notes apart.', 'https://www.islands.com/1865824/what-to-know-before-vietnam-vacation/', 7 FROM "Destination" d WHERE d."slug" = 'hanoi' AND NOT EXISTS (SELECT 1 FROM "DestinationTip" t WHERE t."destinationId" = d."id" AND t."title" = 'Check your 500,000 and 20,000 notes');
INSERT INTO "DestinationTip" ("id","destinationId","topic","title","body","sourceUrl","position") SELECT 'tip_9ca922bd137b461bd976', d."id", 'Money', 'Carry small notes', 'Cash is still the norm for street food, markets and some taxis, and many vendors can''t change big notes. ATMs are easy to find in the city.', 'https://www.eskimo.travel/blog/travel-tips-for-first-time-visiting-vietnam', 8 FROM "Destination" d WHERE d."slug" = 'hanoi' AND NOT EXISTS (SELECT 1 FROM "DestinationTip" t WHERE t."destinationId" = d."id" AND t."title" = 'Carry small notes');
INSERT INTO "DestinationTip" ("id","destinationId","topic","title","body","sourceUrl","position") SELECT 'tip_d8c6e82d56f1217a63f1', d."id", 'Health', 'Don''t drink the tap water', 'Tap water isn''t safe to drink. Bottled and filtered water is cheap and sold everywhere.', 'https://www.eskimo.travel/blog/travel-tips-for-first-time-visiting-vietnam', 9 FROM "Destination" d WHERE d."slug" = 'hanoi' AND NOT EXISTS (SELECT 1 FROM "DestinationTip" t WHERE t."destinationId" = d."id" AND t."title" = 'Don''t drink the tap water');
INSERT INTO "DestinationTip" ("id","destinationId","topic","title","body","sourceUrl","position") SELECT 'tip_2cf5b76cd3de19383711', d."id", 'Etiquette', 'Dress for temples', 'Cover shoulders and knees, take off your shoes, hat and sunglasses, and don''t touch religious objects. Walk clockwise around altars.', 'https://www.islands.com/1865824/what-to-know-before-vietnam-vacation/', 10 FROM "Destination" d WHERE d."slug" = 'hanoi' AND NOT EXISTS (SELECT 1 FROM "DestinationTip" t WHERE t."destinationId" = d."id" AND t."title" = 'Dress for temples');
INSERT INTO "DestinationTip" ("id","destinationId","topic","title","body","sourceUrl","position") SELECT 'tip_10d1c023dd019cc772a4', d."id", 'Safety', 'Never leave your passport as a deposit', 'If you rent a motorbike, check it for damage before you ride off and don''t hand over your passport as security.', 'https://www.islands.com/1865824/what-to-know-before-vietnam-vacation/', 11 FROM "Destination" d WHERE d."slug" = 'hanoi' AND NOT EXISTS (SELECT 1 FROM "DestinationTip" t WHERE t."destinationId" = d."id" AND t."title" = 'Never leave your passport as a deposit');
INSERT INTO "DestinationTip" ("id","destinationId","topic","title","body","sourceUrl","position") SELECT 'tip_339e7d06d1d91b336106', d."id", 'Shopping', 'Haggle with a smile', 'At markets, counter at about half the first price, stay friendly, and walk away if you can''t agree.', 'https://www.islands.com/1865824/what-to-know-before-vietnam-vacation/', 12 FROM "Destination" d WHERE d."slug" = 'hanoi' AND NOT EXISTS (SELECT 1 FROM "DestinationTip" t WHERE t."destinationId" = d."id" AND t."title" = 'Haggle with a smile');
INSERT INTO "DestinationTip" ("id","destinationId","topic","title","body","sourceUrl","position") SELECT 'tip_f94785919c8331d1078f', d."id", 'Transport', 'Get Kakao T for taxis', 'Download Kakao T and link a card before you land. It has English and is more reliable than hailing a taxi in the street.', 'https://mileasia.com/korea/first-time-tips/', 7 FROM "Destination" d WHERE d."slug" = 'seoul' AND NOT EXISTS (SELECT 1 FROM "DestinationTip" t WHERE t."destinationId" = d."id" AND t."title" = 'Get Kakao T for taxis');
INSERT INTO "DestinationTip" ("id","destinationId","topic","title","body","sourceUrl","position") SELECT 'tip_e8d0e01b059520b40c75', d."id", 'Money', 'Don''t tip', 'Tipping isn''t done in Korea. Pay the exact bill.', 'https://mileasia.com/korea/first-time-tips/', 8 FROM "Destination" d WHERE d."slug" = 'seoul' AND NOT EXISTS (SELECT 1 FROM "DestinationTip" t WHERE t."destinationId" = d."id" AND t."title" = 'Don''t tip');
INSERT INTO "DestinationTip" ("id","destinationId","topic","title","body","sourceUrl","position") SELECT 'tip_d0030900d1bbbcabd593', d."id", 'Money', 'Cash for markets and street stalls', 'Visa and Mastercard work in restaurants, shops, cafes and most taxis. Keep some cash for pojangmacha tents, traditional markets and street food.', 'https://mileasia.com/korea/first-time-tips/', 9 FROM "Destination" d WHERE d."slug" = 'seoul' AND NOT EXISTS (SELECT 1 FROM "DestinationTip" t WHERE t."destinationId" = d."id" AND t."title" = 'Cash for markets and street stalls');
INSERT INTO "DestinationTip" ("id","destinationId","topic","title","body","sourceUrl","position") SELECT 'tip_689618d2c5bdeb98bd63', d."id", 'Culture', 'Wear hanbok, get into palaces free', 'Entry to Gyeongbokgung, Changdeokgung, Deoksugung and Gyeonghuigung is free in hanbok. Rentals cost about 15,000 to 25,000 won for 2 to 4 hours.', 'https://mileasia.com/korea/first-time-tips/', 10 FROM "Destination" d WHERE d."slug" = 'seoul' AND NOT EXISTS (SELECT 1 FROM "DestinationTip" t WHERE t."destinationId" = d."id" AND t."title" = 'Wear hanbok, get into palaces free');
INSERT INTO "DestinationTip" ("id","destinationId","topic","title","body","sourceUrl","position") SELECT 'tip_f9d6abe0456f2fea31ba', d."id", 'Transport', 'Last subway is around midnight', 'The subway stops between about midnight and 1am depending on the line. Night buses run until dawn, but less often.', 'https://mileasia.com/korea/first-time-tips/', 11 FROM "Destination" d WHERE d."slug" = 'seoul' AND NOT EXISTS (SELECT 1 FROM "DestinationTip" t WHERE t."destinationId" = d."id" AND t."title" = 'Last subway is around midnight');
INSERT INTO "DestinationTip" ("id","destinationId","topic","title","body","sourceUrl","position") SELECT 'tip_fd7ea638994c7650c97a', d."id", 'Health', 'Check your medicines', 'Codeine cold medicine, some ADHD drugs and other controlled medicines may need approval before you bring them in.', 'https://mileasia.com/korea/first-time-tips/', 12 FROM "Destination" d WHERE d."slug" = 'seoul' AND NOT EXISTS (SELECT 1 FROM "DestinationTip" t WHERE t."destinationId" = d."id" AND t."title" = 'Check your medicines');
INSERT INTO "DestinationTip" ("id","destinationId","topic","title","body","sourceUrl","position") SELECT 'tip_d9adb0177f5a52a92650', d."id", 'Transport', 'Trains take Touch ''n Go or tokens only', 'You can''t tap a bank card, QR code or phone wallet at LRT/MRT gates yet. Buy a single-journey token, or use a Touch ''n Go card (cheaper fares; keep at least RM5 on it).', 'https://www.malaymail.com/news/malaysia/2026/05/22/first-time-using-kuala-lumpurs-trains-here-are-some-tips-including-how-to-pay-tap-in-and-out/220875', 7 FROM "Destination" d WHERE d."slug" = 'kuala-lumpur' AND NOT EXISTS (SELECT 1 FROM "DestinationTip" t WHERE t."destinationId" = d."id" AND t."title" = 'Trains take Touch ''n Go or tokens only');
INSERT INTO "DestinationTip" ("id","destinationId","topic","title","body","sourceUrl","position") SELECT 'tip_94d536dcf88b3b0e9e7b', d."id", 'Transport', 'Buses are cashless', 'Rapid KL buses take no cash, only Touch ''n Go, with at least RM3 on the card. Fares are RM1 to RM5 by zone.', 'https://www.malaymail.com/news/malaysia/2026/05/22/first-time-using-kuala-lumpurs-trains-here-are-some-tips-including-how-to-pay-tap-in-and-out/220875', 8 FROM "Destination" d WHERE d."slug" = 'kuala-lumpur' AND NOT EXISTS (SELECT 1 FROM "DestinationTip" t WHERE t."destinationId" = d."id" AND t."title" = 'Buses are cashless');
INSERT INTO "DestinationTip" ("id","destinationId","topic","title","body","sourceUrl","position") SELECT 'tip_d2e678dc7798a2a9acda', d."id", 'Transport', 'Rapid Kembara pass', 'Unlimited Rapid KL trains, BRT and buses for RM25 for one day or RM55 for three days. It needs a Touch ''n Go card.', 'https://www.malaymail.com/news/malaysia/2026/05/22/first-time-using-kuala-lumpurs-trains-here-are-some-tips-including-how-to-pay-tap-in-and-out/220875', 9 FROM "Destination" d WHERE d."slug" = 'kuala-lumpur' AND NOT EXISTS (SELECT 1 FROM "DestinationTip" t WHERE t."destinationId" = d."id" AND t."title" = 'Rapid Kembara pass');
INSERT INTO "DestinationTip" ("id","destinationId","topic","title","body","sourceUrl","position") SELECT 'tip_77236e1243e239011edc', d."id", 'Transport', 'Use Grab, not street taxis', 'Street taxis may refuse the meter or overcharge. Grab shows the fare first.', 'https://kualalumpurcity.my/kuala-lumpur-travel-tips-first-timers/', 10 FROM "Destination" d WHERE d."slug" = 'kuala-lumpur' AND NOT EXISTS (SELECT 1 FROM "DestinationTip" t WHERE t."destinationId" = d."id" AND t."title" = 'Use Grab, not street taxis');
INSERT INTO "DestinationTip" ("id","destinationId","topic","title","body","sourceUrl","position") SELECT 'tip_363ebc57ea47fc6a3bd9', d."id", 'Etiquette', 'Cover up at mosques and temples', 'Cover shoulders and knees and take off your shoes before going in.', 'https://kualalumpurcity.my/kuala-lumpur-travel-tips-first-timers/', 11 FROM "Destination" d WHERE d."slug" = 'kuala-lumpur' AND NOT EXISTS (SELECT 1 FROM "DestinationTip" t WHERE t."destinationId" = d."id" AND t."title" = 'Cover up at mosques and temples');
INSERT INTO "DestinationTip" ("id","destinationId","topic","title","body","sourceUrl","position") SELECT 'tip_bc765075642b67cac2e9', d."id", 'Money', 'Tipping is optional', 'Restaurants often add a service charge, so tipping isn''t expected. RM2 to RM5 for hotel housekeeping is a kind extra.', 'https://kualalumpurcity.my/kuala-lumpur-travel-tips-first-timers/', 12 FROM "Destination" d WHERE d."slug" = 'kuala-lumpur' AND NOT EXISTS (SELECT 1 FROM "DestinationTip" t WHERE t."destinationId" = d."id" AND t."title" = 'Tipping is optional');
INSERT INTO "DestinationTip" ("id","destinationId","topic","title","body","sourceUrl","position") SELECT 'tip_a14584ecabe61a15357e', d."id", 'Money', 'Change money in town', 'Airport money changers give worse rates. Changers in the city, especially Bukit Bintang, are better.', 'https://kualalumpurcity.my/kuala-lumpur-travel-tips-first-timers/', 13 FROM "Destination" d WHERE d."slug" = 'kuala-lumpur' AND NOT EXISTS (SELECT 1 FROM "DestinationTip" t WHERE t."destinationId" = d."id" AND t."title" = 'Change money in town');
